#pragma once
// The title-menu bitmap font: the PC/PS1/DC option typeface ("NEW GAME",
// "LOAD GAME", "STANDARD"...), A-Z, for the port's title menu.
//
// The game draws its title menu (NEW GAME / LOAD GAME / EXTRA / OPTIONS) with
// it in every mode, so the PC tab writes it into the base tree as
// <USA|JPN>/Data/TITLEFNT.BIN. (It began as the Saturn tab's, in
// SATURN/Data, for the Saturn mode's menu alone; the game still reads a tree
// migrated that way.) No disc contains it as a font, hence the glyphs are
// carried in TitleFontGlyphs.inc (generated by
// tools/gen_title_font.py: 17 letters cut from the Director's Cut's option cells
// and nine - C F H J K Q V X Z - drawn by hand in the same style).
//
// TITLEFNT.BIN, little-endian:
//   +0  'T','F','N','T'
//   +4  u8 height           rows per glyph (11)
//   +5  u8 spacing          gap added to a glyph's width for its advance (3)
//   +6  u8 space advance    width of ' ' (12)
//   +7  u8 glyph count
//   +8  per glyph: u8 character, u8 width, then width*height bytes, row-major,
//       0 = clear, 1 = half-tone (anti-aliased corner), 2 = full
// The game (src/game/TitleMenuFont.cpp) checks the magic and every length.
// Its menu strips are 12 rows tall, so the height must not exceed 12.
//
// With HD textures on, the menu is drawn in a real font instead, written to
// HD/<USA|JPN>/Data/TITLEFNT.TTF beside it: core/HdFonts.h.

#include "core/Types.h"

#include <cstdint>
#include <string>
#include <vector>

namespace re1 {

// Builds the TITLEFNT.BIN image.
std::vector<uint8_t> buildTitleFont();

// Re-reads a TITLEFNT.BIN: true when the header and every glyph length are
// consistent. `glyphs` (optional) receives the glyph count.
bool checkTitleFont(const std::vector<uint8_t>& data, int* glyphs);

}  // namespace re1
